/**
 * TestCaseVfs: wraps a lambda that gets a freshly-constructed
 * VfsFixture. The lambda returns true on success.
 */
class TestCaseVfs : public TestCaseBase<bool>
{
public:
	using Func = std::function<bool( VfsFixture & fix )>;

private:
	Func func;

public:
	TestCaseVfs( const std::string & name_, Func func_ )
	: TestCaseBase<bool>( name_, true ),
	  func( func_ )
	{
	}

	bool run() override
	{
		VfsFixture fix( name );
		return func( fix );
	}
};

/**
 * Format both drives in one shot. Most tests start with this, which
 * matches the typical `format a: ; format b:` two_drives_dynamic
 * preamble.
 */
bool format_both( VfsFixture & fix )
{
	auto r = fix.run( "format a: ; format b: ;" );
	if( !r.all_ok ) {
		CPPDEBUG( Tools::format( "format both failed: %s", r.last_error ) );
		return false;
	}
	return true;
}

bool output_contains( const std::string & haystack, const std::string & needle )
{
	if( haystack.find( needle ) == std::string::npos ) {
		CPPDEBUG( Tools::format( "expected to find '%s' in: '%s'", needle,
		                         haystack ) );
		return false;
	}
	return true;
}

