// ---------------------------------------------------------------------------
// format: create a fresh fs on both drives, then inspect to confirm a
// valid header is present (mounted=true) and no user inodes exist.
// ---------------------------------------------------------------------------
std::shared_ptr<TestCaseBase<bool>> test_case_vfs_format()
{
	return std::make_shared<TestCaseVfs>( __FUNCTION__, []( VfsFixture & fix ) {
		auto r = fix.run( "format a: ; format b: ;" );
		if( !r.all_ok ) {
			return false;
		}
		if( !output_contains( r.output, "Drive formatted: a" ) ) {
			return false;
		}
		if( !output_contains( r.output, "Drive formatted: b" ) ) {
			return false;
		}

		auto ia = inspect_drive( fix, "a", false );
		auto ib = inspect_drive( fix, "b", false );
		if( !ia.mounted || !ib.mounted ) {
			CPPDEBUG( "post-format: dynamic mount failed" );
			return false;
		}
		if( !ia.inodes.empty() || !ib.inodes.empty() ) {
			CPPDEBUG( "post-format: expected no inodes on either drive" );
			return false;
		}
		return true;
	} );
}

