// ---------------------------------------------------------------------------
// touch: create an empty file, confirm inode exists with file_len=0
// ---------------------------------------------------------------------------
std::shared_ptr<TestCaseBase<bool>> test_case_vfs_touch()
{
	return std::make_shared<TestCaseVfs>( __FUNCTION__, []( VfsFixture & fix ) {
		if( !format_both( fix ) ) {
			return false;
		}

		auto r = fix.run( "a: ; touch hello.txt ;" );
		if( !r.all_ok ) {
			return false;
		}

		auto ia = inspect_drive( fix, "a" );
		auto * f = find_file( ia, "hello.txt" );
		if( !f ) {
			CPPDEBUG( "touch: file not visible on disk" );
			return false;
		}
		if( f->file_len != 0 ) {
			CPPDEBUG( Tools::format( "touch: expected file_len 0, got %d",
			                         f->file_len ) );
			return false;
		}
		if( f->data_pages_count != 0 ) {
			CPPDEBUG( "touch: expected no external pages" );
			return false;
		}
		return true;
	} );
}

