// ---------------------------------------------------------------------------
// mv: rename within drive a:, original is gone, target is present
// ---------------------------------------------------------------------------
std::shared_ptr<TestCaseBase<bool>> test_case_vfs_mv_rename()
{
	return std::make_shared<TestCaseVfs>( __FUNCTION__, []( VfsFixture & fix ) {
		if( !format_both( fix ) ) {
			return false;
		}
		auto r = fix.run( "a: ; test_count old 3 ; mv old new ;" );
		if( !r.all_ok ) {
			return false;
		}

		auto ia = inspect_drive( fix, "a" );
		if( find_file( ia, "old" ) ) {
			CPPDEBUG( "mv: old name still visible on disk" );
			return false;
		}
		// mv passes the absolute path /a/new as the new name to
		// rename_file(); accept either the bare or absolute form.
		auto * fn = find_file( ia, "new" );
		if( !fn ) {
			fn = find_file( ia, "/a/new" );
		}
		if( !fn ) {
			CPPDEBUG( "mv: renamed file missing on disk" );
			return false;
		}
		std::string expected = "1\n2\n3\n";
		if( !bytes_equal( fn->contents, expected, "mv content" ) ) {
			return false;
		}
		return true;
	} );
}

