// ---------------------------------------------------------------------------
// cleanup: create+delete to leave trash, run cleanup, verify it succeeds
// ---------------------------------------------------------------------------
std::shared_ptr<TestCaseBase<bool>> test_case_vfs_cleanup()
{
	return std::make_shared<TestCaseVfs>( __FUNCTION__, []( VfsFixture & fix ) {
		if( !format_both( fix ) ) {
			return false;
		}
		auto r = fix.run(
			"a: ; touch a1 ; touch a2 ; rm a1 ; cleanup ; ls ;" );
		if( !r.all_ok ) {
			return false;
		}
		if( !output_contains( r.output, "Cleanup completed" ) ) {
			return false;
		}
		// a2 still present, a1 gone
		if( !output_contains( r.output, "a2" ) ) {
			return false;
		}

		auto ia = inspect_drive( fix, "a" );
		if( find_file( ia, "a1" ) ) {
			CPPDEBUG( "cleanup: deleted file still on disk" );
			return false;
		}
		if( !find_file( ia, "a2" ) ) {
			CPPDEBUG( "cleanup: surviving file is missing" );
			return false;
		}
		return true;
	} );
}

